import { CSSProperties, ReactNode } from 'react';
import { ConvertibleUnit, FormatOptions, Unit } from '@dynatrace-sdk/units';
import { Threshold } from '../../../core/types/threshold-types.js';
import { Formatter } from '../../core/types/formatter.js';
import { SparklineThresholdProps } from '../../sparkline/slots/Threshold.js';
import { SparklineYAxisProps } from '../../sparkline/slots/YAxis.js';
import { SparklineVariant } from '../../sparkline/types/sparkline.js';
export type SingleValueUnit = Unit | (string & {});
/** Single Value Alingment */
export type SingleValueAlignment = 'start' | 'center' | 'end';
/** Props for SingleValue */
export interface SingleValueProps {
    /** Optional label text to show above the value. */
    label?: string;
    /** Optional icon to show left of the value. */
    prefixIcon?: ReactNode;
    /** State of the value. This affects text and prefix icon color.
     * @defaultValue 'default'
     */
    color?: string;
    /** Optional unit to show in the right of the value */
    unit?: SingleValueUnit;
    /** Data to show within the chart. */
    data: string | number;
    /** If specified, value will be formatted with given formatter options. */
    formatter?: Formatter | FormatOptions<Unit, ConvertibleUnit>;
    /** Threshold configurations defining conditions to match a given value. */
    thresholds?: Threshold[];
    /** Horizontal alignment of icon, value and unit. */
    alignment?: SingleValueAlignment;
    /** Show the loading indicator when truly.
     * @defaultValue false
     */
    loading?: boolean;
    /** Class names to be attached to the outer container. */
    className?: string;
    /** Inline styles that will override the outer container. */
    style?: CSSProperties;
}
/** Configuration for SingleValue */
export interface SingleValueSparklineConfig {
    /** Sparkline color **/
    color?: string;
    /** Sparkline variant (line, area) **/
    variant?: SparklineVariant;
    /** Thresholds props for the sparkline */
    thresholds?: SparklineThresholdProps[];
    /** Y-axis props for the sparkline */
    yAxis?: SparklineYAxisProps;
    /** Whether Sparkline shows X Axis ticks or not **/
    showTicks?: boolean;
    /** Gap policy */
    gapPolicy?: 'connect' | 'gap';
}
export interface SingleValueConfigProperties {
    /** Optional label text to show beneath the value. */
    label?: string;
    /** State of the value. This affects text and prefix icon color.
     * @defaultValue 'default'
     */
    color?: string;
    /** Optional unit to show in the right of the value */
    unit?: SingleValueUnit;
    /** If specified, value will be formatted with given formatter options. */
    formatter?: Formatter | FormatOptions<Unit, ConvertibleUnit>;
    /** Threshold configurations defining conditions to match a given value. */
    thresholds?: Threshold[];
    /** Sparkline config properties */
    sparkline?: SingleValueSparklineConfig;
    /** Horizontal alignment of icon, value and unit.
     * @defaultValue 'start'
     */
    alignment?: SingleValueAlignment;
}
